#!/bin/bash
set -euo pipefail
base=/opt/mun-new-year-leads
web=/var/www/mun-new-year
test -s "$base/bot-token"
test -s "$base/chat-id"
test -s "$web/index.html"
systemctl cat mun-new-year-leads.service >/dev/null
stage=$(mktemp -d)
trap 'rm -rf "$stage"' EXIT
export MUN_RELEASE_STAGE="$stage"
python3 - <<'MUN_STAGE'
import json, os
from pathlib import Path
files = json.loads('{"form.js": "(() => {\\n  const form = document.querySelector(\'.booking-card\');\\n  if (!form) return;\\n  const button = form.querySelector(\'button[type=\\"submit\\"]\');\\n  const note = document.querySelector(\'#form-note\');\\n  // Enable only in the reviewed deployment, after backend and documents are ready.\\n  const enabled = form.dataset.acceptLeads === \'true\' && location.origin === \'https://ng.munlaunge.ru\';\\n  let sending = false;\\n  function status(text, state) { note.textContent = text; note.dataset.state = state; }\\n  button.disabled = !enabled;\\n  if (enabled) status(\'Свяжемся с вами и обсудим детали праздника.\', \'idle\');\\n  form.addEventListener(\'submit\', async event => {\\n    event.preventDefault();\\n    if (!enabled || sending || !form.reportValidity()) return;\\n    const fields = new FormData(form);\\n    const phone = String(fields.get(\'phone\') || \'\').replace(/[\\\\s()+-]/g, \'\');\\n    if (!/^[78]\\\\d{10}$/.test(phone)) {\\n      status(\'Укажите телефон из 11 цифр, начиная с +7 или 8.\', \'error\');\\n      form.elements.phone.focus(); return;\\n    }\\n    const payload = Object.fromEntries([\'name\',\'phone\',\'date\',\'guests\',\'hall\',\'menu\',\'website\'].map(key => [key, String(fields.get(key) || \'\').trim()]));\\n    payload.consent = form.elements.consent.checked;\\n    sending = true; button.disabled = true; button.textContent = \'Отправляем…\';\\n    status(\'Отправляем вашу заявку…\', \'pending\');\\n    const controller = new AbortController();\\n    const timer = setTimeout(() => controller.abort(), 30000);\\n    try {\\n      const response = await fetch(\'https://api.munlaunge.ru/leads\', {\\n        method: \'POST\', headers: {\'Content-Type\':\'application/json\'},\\n        body: JSON.stringify(payload), signal: controller.signal, credentials: \'omit\'\\n      });\\n      let result;\\n      try { result = await response.json(); } catch (_) { throw new Error(\'Не удалось подтвердить отправку. Позвоните нам: +7 (8352) 75-55-05.\'); }\\n      if (!response.ok || result.ok !== true) throw new Error(result.error || \'Не удалось подтвердить отправку. Позвоните нам: +7 (8352) 75-55-05.\');\\n      status(\'Заявка отправлена! Мы свяжемся с вами. Дата закрепляется после согласования и предоплаты 50%.\', \'success\');\\n      form.reset(); form.dispatchEvent(new Event(\'booking:sent\'));\\n    } catch (error) {\\n      status(error.name === \'AbortError\' || error instanceof TypeError ? \'Не удалось подтвердить доставку. Данные сохранены в полях. Позвоните нам: +7 (8352) 75-55-05.\' : error.message, \'error\');\\n    } finally {\\n      clearTimeout(timer); sending = false; button.disabled = false; button.textContent = \'Оставить заявку\';\\n    }\\n  });\\n  form.addEventListener(\'booking:sent\', () => {\\n    document.querySelector(\'#date\').dispatchEvent(new Event(\'change\'));\\n  });\\n})();\\n", "form.css": "\\n.form-consent{display:flex!important;align-items:flex-start;gap:12px;margin:20px 0;font-size:13px;line-height:1.6;font-weight:400}\\n.form-consent input{width:18px!important;height:18px!important;min-width:18px;margin:4px 0 0;padding:0;accent-color:#772936}\\n.form-consent a{text-decoration:underline;text-underline-offset:3px}\\n.form-trap{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}\\n#form-note[data-state=\\"error\\"]{color:#ffb4b4}#form-note[data-state=\\"success\\"]{color:#d4efd6}\\n.preview-note{padding:12px 20px;background:#f5e5c6;color:#35251d;text-align:center;margin:0;font-size:14px}\\n", "privacy.html": "<!doctype html><html lang=\\"ru\\"><head><meta charset=\\"utf-8\\"><meta name=\\"viewport\\" content=\\"width=device-width,initial-scale=1\\"><meta name=\\"robots\\" content=\\"noindex\\"><title>Политика обработки персональных данных — МУН</title><style>body{margin:0;background:#faf7f2;color:#302629;font:16px/1.7 system-ui,sans-serif}main{max-width:800px;margin:auto;padding:36px 22px 64px}h1{font-size:clamp(28px,5vw,38px);line-height:1.2}h2{font-size:21px;margin-top:32px}a{color:#762c3d;text-underline-offset:3px}.date{color:#71656a;font-size:14px}@media print{body{background:white}main{padding:0}h2{break-after:avoid}p{orphans:3;widows:3}}</style></head><body><main><h1>Политика обработки персональных данных</h1>\\n<p class=\\"date\\">Сайт ng.munlaunge.ru · Редакция от 27 сентября 2026 года</p>\\n<h2>1. Общие положения</h2>\\n<p>Настоящая политика определяет порядок обработки персональных данных посетителей сайта ng.munlaunge.ru, обращающихся по вопросам проведения мероприятий и бронирования.</p>\\n<p>Оператор — Общество с ограниченной ответственностью «МУН МЭДЖИК», ИНН 2100033211, ОГРН 1262100003164. Юридический адрес: 428022, Россия, Чувашская Республика, г. Чебоксары, Марпосадское шоссе, д. 1. Электронная почта для обращений: <a href=\\"mailto:munmedjik@yandex.ru\\">munmedjik@yandex.ru</a>.</p>\\n<h2>2. Цели и состав данных</h2>\\n<p>Оператор обрабатывает имя и номер телефона для ответа на обращение, подбора даты, зала и меню, согласования условий мероприятия и бронирования. Дополнительно посетитель может указать желаемую дату, количество гостей, зал и вариант меню.</p>\\n<p>Для работы и защиты сайта могут обрабатываться технические сведения: IP-адрес, время запроса, адрес запрашиваемой страницы и сведения о браузере. При отправке заявки обрабатывается также факт предоставления согласия.</p>\\n<p>Форма не предназначена для сбора специальных категорий данных, биометрических данных или сведений о других гостях. Отправка заявки не является подтверждением бронирования и не означает согласия на рекламные рассылки.</p>\\n<h2>3. Основания и способы обработки</h2>\\n<p>Обработка осуществляется в соответствии с Федеральным законом № 152-ФЗ «О персональных данных» на основании согласия посетителя, а в предусмотренных законом случаях — для заключения договора по его инициативе, исполнения договора или выполнения обязанностей оператора.</p>\\n<p>Согласие на обработку данных из формы предоставляется отдельно при её отправке. Посетитель вправе не отправлять форму и обратиться в заведение по телефону.</p>\\n<p>Обработка может включать сбор, запись, систематизацию, накопление, хранение, уточнение, извлечение, использование, предоставление доступа, передачу, блокирование, удаление и уничтожение данных с использованием средств автоматизации и без них.</p>\\n<h2>4. Сроки хранения и удаление</h2>\\n<p>Данные обращения обрабатываются в течение срока, необходимого для его рассмотрения и согласования бронирования. При заключении договора необходимые сведения сохраняются в сроки, предусмотренные законодательством и исполнением договора.</p>\\n<p>По достижении цели обработки, при отзыве согласия или выявлении неправомерной обработки данные подлежат удалению либо уничтожению в установленные законом сроки, если отсутствует другое законное основание для продолжения обработки. Удаляются электронные записи и рабочие копии, включая сообщения с заявками; бумажные копии, если они создавались, уничтожаются способом, исключающим восстановление данных.</p>\\n<h2>5. Защита данных</h2>\\n<p>Оператор обязан принимать необходимые правовые, организационные и технические меры для защиты данных от неправомерного доступа, изменения, раскрытия, утраты и уничтожения. Доступ к заявкам должен предоставляться только лицам, которым он необходим для выполнения рабочих обязанностей.</p>\\n<h2>6. Права посетителя и обращения</h2>\\n<p>Посетитель вправе получить информацию об обработке своих данных, потребовать их уточнения, блокирования или удаления при наличии предусмотренных законом оснований, отозвать согласие и обжаловать действия оператора в Роскомнадзор или суд.</p>\\n<p>Обращения направляются на <a href=\\"mailto:munmedjik@yandex.ru\\">munmedjik@yandex.ru</a> или по юридическому адресу оператора. Укажите суть обращения и сведения, позволяющие найти вашу заявку. При необходимости оператор может запросить подтверждение, что обращение поступило от субъекта данных или его представителя.</p>\\n<p>Отзыв согласия не влияет на правомерность обработки, выполненной до его получения. Обращения рассматриваются в сроки, установленные законодательством Российской Федерации.</p>\\n<h2>7. Изменения политики</h2>\\n<p>Оператор актуализирует политику при изменении целей и условий обработки. Дата редакции указывается в начале документа. Актуальная редакция должна быть доступна на сайте.</p></main></body></html>", "consent.html": "<!doctype html><html lang=\\"ru\\"><meta charset=\\"utf-8\\"><meta name=\\"viewport\\" content=\\"width=device-width,initial-scale=1\\"><meta name=\\"robots\\" content=\\"noindex\\"><title>Согласие на обработку персональных данных — МУН</title><style>body{background:#faf7f2;color:#2c2323;font:17px/1.65 system-ui;margin:0 auto;padding:28px 22px;max-width:820px}h1{font-size:32px;line-height:1.2}h2{font-size:22px;margin-top:28px}a{color:#772936}.draft{background:#f5e5c6;padding:16px;border-radius:8px}</style><body><a href=\\"index.html#request\\">← К форме</a><h1>Согласие на обработку персональных данных</h1><p>Редакция от 27 сентября 2026 года</p><p>Отмечая отдельный флажок и отправляя форму заявки на ng.munlaunge.ru, я добровольно даю Обществу с ограниченной ответственностью «МУН МЭДЖИК» (ИНН 2100033211, адрес: 428022, Россия, Чувашская Республика, г. Чебоксары, Марпосадское шоссе, д. 1) согласие на обработку указанных мной сведений.</p><h2>Цель</h2><p>Обратная связь по моей заявке на корпоратив, подбор даты, зала и меню, согласование условий бронирования.</p><h2>Состав данных</h2><p>Моё имя, номер телефона и добровольно указанные детали: дата, количество гостей, зал и меню; факт предоставления согласия.</p><h2>Действия</h2><p>Сбор, запись, систематизация, хранение, уточнение, использование, предоставление уполномоченным сотрудникам, блокирование и удаление с использованием средств автоматизации и без них. Для доставки и рассмотрения обращения используются услуги хостинга и электронных коммуникаций. Обработка может включать передачу данных поставщикам этих услуг и за пределы Российской Федерации при соблюдении установленных законом требований.</p><h2>Срок и отзыв</h2><p>До достижения цели обработки обращения или отзыва согласия, если отсутствует другое предусмотренное законом основание для продолжения обработки. Согласие можно отозвать по адресу <a href=\\"mailto:munmedjik@yandex.ru\\">munmedjik@yandex.ru</a> или письменно по юридическому адресу оператора. При наличии другого законного основания обработка может продолжаться в предусмотренных законом пределах.</p><p>Это согласие не распространяется на рекламные рассылки или публичное распространение данных. <a href=\\"privacy.html\\">Политика обработки персональных данных</a> доступна отдельно.</p></body></html>", "server.py": "\\"\\"\\"MUN booking receiver. Bind only to localhost behind nginx.\\"\\"\\"\\nimport hashlib\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport re\\nimport sqlite3\\nimport subprocess\\nimport sys\\nimport time\\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\\n\\nORIGIN = \'https://ng.munlaunge.ru\'\\nDATES = {\'\', \'other\'} | {f\'2026-12-{day}\' for day in (18, 19, 24, 25, 26, 27)}\\nHALLS = {\'\', \'Основной зал\', \'Банкетные комнаты\', \'Караоке-зал\'}\\n\\ndef telegram(text):\\n    directory = Path(os.environ.get(\'CREDENTIALS_DIRECTORY\', \'/opt/mun-new-year-leads\'))\\n    token = (directory / \'bot-token\').read_text().strip()\\n    chat = (directory / \'chat-id\').read_text().strip()\\n    if not re.fullmatch(r\'\\\\d+:[\\\\w-]+\', token) or chat != \'-5263234967\':\\n        raise RuntimeError(\'Invalid configuration\')\\n    payload = json.dumps({\'chat_id\': chat, \'text\': text, \'link_preview_options\': {\'is_disabled\': True}}, ensure_ascii=False)\\n    # Both credentials and personal data travel on stdin, never in process arguments.\\n    config = \'url = \' + json.dumps(\'https://api.telegram.org/bot\' + token + \'/sendMessage\') + \'\\\\n\'\\n    config += \'header = \\"Content-Type: application/json\\"\\\\ndata = \' + json.dumps(payload, ensure_ascii=False) + \'\\\\n\'\\n    result = subprocess.run([\'curl\', \'-6\', \'-sS\', \'--connect-timeout\', \'5\', \'--max-time\', \'15\', \'--config\', \'-\'],\\n                            input=config, text=True, capture_output=True, timeout=18)\\n    if result.returncode or not json.loads(result.stdout).get(\'ok\'):\\n        raise RuntimeError(\'Delivery failed\')\\n\\ndef validate(data):\\n    if not isinstance(data, dict):\\n        raise ValueError(\'Invalid request\')\\n    if data.get(\'consent\') is not True:\\n        raise ValueError(\'Необходимо согласие на обработку данных\')\\n    values = {}\\n    for key in [\'name\', \'phone\', \'date\', \'guests\', \'hall\', \'menu\', \'website\']:\\n        value = data.get(key, \'\')\\n        if not isinstance(value, str) or len(value) > 100 or any(ord(c) < 32 for c in value):\\n            raise ValueError(\'Проверьте заполненные поля\')\\n        values[key] = value.strip()\\n    if values[\'website\']:\\n        raise ValueError(\'Не удалось отправить заявку\')\\n    if not 2 <= len(values[\'name\']) <= 80:\\n        raise ValueError(\'Укажите имя\')\\n    phone = re.sub(r\'[\\\\s()+-]\', \'\', values[\'phone\'])\\n    if not re.fullmatch(r\'[78]\\\\d{10}\', phone):\\n        raise ValueError(\'Укажите телефон из 11 цифр\')\\n    values[\'phone\'] = \'+7\' + phone[1:]\\n    if values[\'date\'] not in DATES or values[\'hall\'] not in HALLS or values[\'menu\'] not in {\'\', \'3500\', \'4000\'}:\\n        raise ValueError(\'Проверьте дату, зал и меню\')\\n    if values[\'guests\'] and (not values[\'guests\'].isdigit() or not 1 <= int(values[\'guests\']) <= 120):\\n        raise ValueError(\'Укажите количество гостей от 1 до 120\')\\n    return values\\n\\ndef message(v):\\n    price = str(int(v[\'menu\']) + (300 if v[\'date\'] in {\'2026-12-25\', \'2026-12-26\'} else 0)) + \' ₽\' if v[\'menu\'] else \'Не выбрано\'\\n    date = \'Другая дата — обсудим\' if v[\'date\'] == \'other\' else (v[\'date\'][-2:] + \' декабря 2026\' if v[\'date\'] else \'Не выбрана\')\\n    return \'\\\\n\'.join([\'Новая заявка · МУН · Новый год\', \'Имя: \' + v[\'name\'], \'Телефон: \' + v[\'phone\'],\\n                      \'Дата: \' + date,\\n                      \'Гостей: \' + (v[\'guests\'] or \'Не указано\'), \'Зал: \' + (v[\'hall\'] or \'Помогите выбрать\'),\\n                      \'Меню: \' + price, \'Источник: ng.munlaunge.ru\', \'Согласие на обработку данных: подтверждено\'])\\n\\nclass Handler(BaseHTTPRequestHandler):\\n    def log_message(self, *args):\\n        pass  # Never log request bodies or personal details.\\n\\n    def setup(self):\\n        super().setup()\\n        self.connection.settimeout(10)\\n\\n    def reply(self, status, data):\\n        body = json.dumps(data, ensure_ascii=False).encode()\\n        self.send_response(status)\\n        self.send_header(\'Content-Type\', \'application/json; charset=utf-8\')\\n        self.send_header(\'Cache-Control\', \'no-store\')\\n        if self.headers.get(\'Origin\') == ORIGIN:\\n            self.send_header(\'Access-Control-Allow-Origin\', ORIGIN)\\n            self.send_header(\'Vary\', \'Origin\')\\n        self.send_header(\'Content-Length\', str(len(body)))\\n        self.end_headers()\\n        self.wfile.write(body)\\n\\n    def do_GET(self):\\n        self.reply(200 if self.path == \'/health\' else 404, {\'ok\': self.path == \'/health\'})\\n\\n    def do_OPTIONS(self):\\n        if self.path != \'/leads\' or self.headers.get(\'Origin\') != ORIGIN:\\n            return self.reply(403, {\'ok\': False})\\n        self.send_response(204)\\n        self.send_header(\'Access-Control-Allow-Origin\', ORIGIN)\\n        self.send_header(\'Access-Control-Allow-Methods\', \'POST\')\\n        self.send_header(\'Access-Control-Allow-Headers\', \'Content-Type\')\\n        self.send_header(\'Vary\', \'Origin\')\\n        self.end_headers()\\n\\n    def do_POST(self):\\n        if self.path != \'/leads\':\\n            return self.reply(404, {\'ok\': False})\\n        if self.headers.get(\'Origin\') != ORIGIN:\\n            return self.reply(403, {\'ok\': False})\\n        # Only enable after consent documents and the frontend are ready.\\n        if os.environ.get(\'MUN_ACCEPT_LEADS\') != \'1\':\\n            return self.reply(503, {\'ok\': False, \'error\': \'Приём заявок ещё настраивается\'})\\n        try:\\n            length = int(self.headers.get(\'Content-Length\', \'0\'))\\n            if not 0 < length <= 4096 or self.headers.get_content_type() != \'application/json\':\\n                return self.reply(400, {\'ok\': False, \'error\': \'Некорректный запрос\'})\\n            values = validate(json.loads(self.rfile.read(length)))\\n        except (ValueError, UnicodeError):\\n            return self.reply(400, {\'ok\': False, \'error\': \'Проверьте поля и согласие на обработку данных\'})\\n        digest = hashlib.sha256(json.dumps(values, sort_keys=True).encode()).hexdigest()\\n        now = time.time()\\n        db_path = Path(os.environ.get(\'STATE_DIRECTORY\', \'/var/lib/mun-new-year-leads\')) / \'delivery.sqlite\'\\n        with sqlite3.connect(db_path) as db:\\n            db.execute(\'CREATE TABLE IF NOT EXISTS delivery (hash TEXT, time REAL, sent INTEGER)\')\\n            db.execute(\'DELETE FROM delivery WHERE time < ?\', (now - 86400,))\\n            if db.execute(\'SELECT 1 FROM delivery WHERE hash=? AND sent=1 AND time>?\', (digest, now-600)).fetchone():\\n                return self.reply(200, {\'ok\': True})\\n            if db.execute(\'SELECT count(*) FROM delivery WHERE time>?\', (now-3600,)).fetchone()[0] >= 60:\\n                return self.reply(429, {\'ok\': False, \'error\': \'Попробуйте позже или позвоните нам\'})\\n            db.execute(\'INSERT INTO delivery VALUES (?,?,0)\', (digest, now))\\n            db.commit()\\n            try:\\n                telegram(message(values))\\n            except Exception:\\n                return self.reply(502, {\'ok\': False, \'error\': \'Доставка не подтверждена. Пожалуйста, позвоните нам\'})\\n            db.execute(\'UPDATE delivery SET sent=1 WHERE hash=? AND time=?\', (digest, now))\\n        self.reply(200, {\'ok\': True})\\n\\nif __name__ == \'__main__\':\\n    if \'--test\' in sys.argv:\\n        telegram(\'✅ Тест обработчика формы МУН. Соединение с Telegram работает. Это не заявка гостя.\')\\n        print(\'TEST SENT\')\\n    else:\\n        HTTPServer((\'127.0.0.1\', 8091), Handler).serve_forever()\\n"}')
for name, content in files.items():
    (Path(os.environ['MUN_RELEASE_STAGE']) / name).write_text(content)
MUN_STAGE
python3 - "$stage" <<'MUN_HTML'
from pathlib import Path
import sys
web=Path('/var/www/mun-new-year')
stage=Path(sys.argv[1])
s=(web/'index.html').read_text()
if 'booking-card' not in s or 'id="form-note"' not in s:
    raise SystemExit('Unexpected page structure; no changes made')
if 'form.js?v=booking-1' not in s:
    s=s.replace('</head>', '<link rel="stylesheet" href="form.css?v=booking-1"><script src="form.js?v=booking-1" defer></script></head>')
if 'data-accept-leads="true"' not in s:
    s=s.replace('<form class="booking-card"', '<form data-accept-leads="true" class="booking-card"')
if 'name="consent"' not in s:
    consent='<label class="form-consent"><input type="checkbox" name="consent" required><span>Даю <a href="consent.html" target="_blank" rel="noopener">согласие на обработку персональных данных</a>. <a href="privacy.html" target="_blank" rel="noopener">Политика обработки данных</a>.</span></label><div class="form-trap" aria-hidden="true"><label>Ваш сайт<input name="website" tabindex="-1" autocomplete="off"></label></div>'
    anchor='<button class="button" type="submit"'
    if s.count(anchor)!=1: raise SystemExit('Submit button not found; stopped')
    s=s.replace(anchor,consent+anchor)
s=s.replace('id="form-note">','id="form-note" role="status" aria-live="polite">')
(stage/'index.html').write_text(s)
MUN_HTML
backup="$base/backups/$(date +%Y%m%d-%H%M%S)"
mkdir -p "$backup/web" "$backup/config"
chmod 700 "$base/backups" "$backup"
for name in index.html form.js form.css privacy.html consent.html; do
  if test -f "$web/$name"; then cp -a "$web/$name" "$backup/web/"; fi
done
cp -a "$base/server.py" "$backup/config/server.py"
mkdir -p /etc/systemd/system/mun-new-year-leads.service.d
conf=/etc/systemd/system/mun-new-year-leads.service.d/booking.conf
if test -f "$conf"; then cp -a "$conf" "$backup/config/booking.conf"; fi
restore() {
  cp -a "$backup/config/server.py" "$base/server.py"
  if test -f "$backup/config/booking.conf"; then cp -a "$backup/config/booking.conf" "$conf"; else rm -f "$conf"; fi
  systemctl daemon-reload
  systemctl restart mun-new-year-leads
  echo "Update stopped; previous backend restored. Backup: $backup"
}
install -m 644 "$stage/server.py" "$base/server.py"
chmod 755 "$base"
printf '[Service]\nEnvironment=MUN_ACCEPT_LEADS=1\n' > "$conf"
systemctl daemon-reload
systemctl restart mun-new-year-leads
ready=0
for i in 1 2 3 4 5; do
  if curl -fsS --max-time 3 http://127.0.0.1:8091/health >/dev/null; then ready=1; break; fi
  sleep 1
done
if test "$ready" != 1; then restore; exit 1; fi
# End-to-end HTTP test under the service user, including its credentials.
if ! python3 - <<'MUN_TEST'
import json, urllib.request, time
payload={'name':'ТЕСТ - настройка формы','phone':'+70000000000','date':'2026-12-25','guests':'10','hall':'Основной зал','menu':'3500','consent':True}
req=urllib.request.Request('https://api.munlaunge.ru/leads', data=json.dumps(payload).encode(), headers={'Content-Type':'application/json','Origin':'https://ng.munlaunge.ru'})
with urllib.request.urlopen(req,timeout=30) as res:
    data=json.load(res)
    assert data.get('ok') is True
print('TEST SENT - synthetic booking, 25 December, 3800 RUB')
MUN_TEST
then restore; exit 1; fi
for name in form.js form.css privacy.html consent.html; do install -m 644 "$stage/$name" "$web/$name"; done
install -m 644 "$stage/index.html" "$web/index.html.new"
mv "$web/index.html.new" "$web/index.html"
printf 'FORM READY\nBackup: %s\n' "$backup"
